const VISITOR_COUNTER_URL =
  import.meta.env.VITE_VISITOR_COUNTER_URL?.trim() ||
  'https://script.google.com/macros/s/AKfycbwvrMmufXUMd_jUfEho4lyiix-aRf8eFu575KnYXvCdovqCShQ5RGkCk0BJAOVZcwvh/exec';
let visitorCountRequested = false;

const formatStars = (value) => {
  if (value == null) return '—';
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(1)}M`;
  if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
  return String(value);
};

function App() {
  const [lang, setLang] = useState('en');
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState('All');
  const [stars, setStars] = useState({});
  const [loading, setLoading] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [visitorCount, setVisitorCount] = useState(30000);
  const [visitorCountLoading, setVisitorCountLoading] = useState(true);
  const t = copy[lang];

  const categories = useMemo(() => ['All', ...new Set(repositories.map((item) => item.category))], []);
  const filtered = useMemo(() => repositories.filter((item) => {
    const searchable = `${item.repo} ${item.en.name} ${item.pt.name} ${item.en.purpose} ${item.pt.purpose} ${item.category}`.toLowerCase();
    return (category === 'All' || item.category === category) && searchable.includes(query.toLowerCase());
  }), [query, category]);

  const loadStars = async () => {
    setLoading(true);
    const results = await Promise.all(repositories.map(async (item) => {
      try {
        const response = await fetch(`https://api.github.com/repos/${item.repo}`, { headers: { Accept: 'application/vnd.github+json' } });
        if (!response.ok) throw new Error('GitHub request failed');
        const data = await response.json();
        return [item.repo, data.stargazers_count];
      } catch {
        return [item.repo, null];
      }
    }));
    setStars(Object.fromEntries(results));
    setLoading(false);
  };

  useEffect(() => { loadStars(); }, []);

  useEffect(() => {
    if (visitorCountRequested) return;
    visitorCountRequested = true;

    const registerVisit = async () => {
      if (!VISITOR_COUNTER_URL) {
        console.warn('VITE_VISITOR_COUNTER_URL is missing from .env');
        setVisitorCountLoading(false);
        return;
      }

      try {
        const separator = VISITOR_COUNTER_URL.includes('?') ? '&' : '?';
        const response = await fetch(
          `${VISITOR_COUNTER_URL}${separator}action=visit&t=${Date.now()}`,
          { method: 'GET', cache: 'no-store' }
        );

        if (!response.ok) {
          throw new Error(`Visitor counter returned HTTP ${response.status}`);
        }

        const data = await response.json();
        const nextCount = Number(data?.visitors);

        if (data?.success && Number.isFinite(nextCount)) {
          setVisitorCount(nextCount);
        }
      } catch (error) {
        console.error('Visitor counter error:', error);
      } finally {
        setVisitorCountLoading(false);
      }
    };

    registerVisit();
  }, []);

  const freeCount = repositories.filter((item) => item.free === 'free').length;
  const noApiCount = repositories.filter((item) => item.api !== 'required').length;
  const starTotal = Object.values(stars).reduce((sum, value) => sum + (value || 0), 0);

  const chooseCategory = (next) => {
    setCategory(next);
    setMenuOpen(false);

    // After changing the sidebar filter, move the user directly to
    // the repositories section so the selected results are visible.
    window.requestAnimationFrame(() => {
      document.getElementById('repositories')?.scrollIntoView({
        behavior: 'smooth',
        block: 'start',
      });
    });
  };

  return <div className="app-shell">
    <button className="mobile-menu" onClick={() => setMenuOpen(true)} aria-label={t.menu}><Icon name="menu" /></button>
    <div className={`sidebar-backdrop ${menuOpen ? 'show' : ''}`} onClick={() => setMenuOpen(false)} />

    <aside className={`sidebar ${menuOpen ? 'open' : ''}`}>
      <div className="sidebar-head">
        <a className="brand" href="#top" onClick={() => setMenuOpen(false)}>
          <span className="brand-mark"><Icon name="code" size={22} /></span>
          <span><strong>{t.brand}</strong><small>{t.smallBrand}</small></span>
        </a>
        <button className="sidebar-close" onClick={() => setMenuOpen(false)} aria-label={t.close}><Icon name="close" /></button>
      </div>

      <nav className="nav-block">
        <span className="nav-label">Menu</span>
        <a className="nav-item active" href="#top" onClick={() => setMenuOpen(false)}><Icon name="grid" size={18}/>{t.dashboard}</a>
        <a className="nav-item" href="#video-lab" onClick={() => setMenuOpen(false)}><Icon name="play" size={18}/>{t.videoLab}</a>
        <a className="nav-item" href="#voice-lab" onClick={() => setMenuOpen(false)}><Icon name="phone" size={18}/>{lang === 'pt' ? 'Servidor de Voz IA' : 'AI Phone Server'}</a>
        <a className="nav-item" href="#trading-lab" onClick={() => setMenuOpen(false)}><Icon name="chart" size={18}/>{lang === 'pt' ? 'Trading Diário' : 'Daily Trading'}</a>
        <a className="nav-item" href="#repositories" onClick={() => setMenuOpen(false)}><Icon name="github" size={18}/>{t.repositories}<span className="nav-count">{repositories.length}</span></a>
      </nav>

      <div className="nav-block category-list">
        <span className="nav-label">{t.categories}</span>
        <button className={`nav-item ${category === 'All' ? 'active' : ''}`} onClick={() => chooseCategory('All')}><span className="category-dot all-dot" />{t.all}</button>
        {categories.slice(1).map((name, index) => <button key={name} className={`nav-item ${category === name ? 'active' : ''}`} onClick={() => chooseCategory(name)}>
          <span className="category-dot" style={{ background: repositories.find((item) => item.category === name)?.accent }} />{name}<span className="nav-count">{repositories.filter((item) => item.category === name).length}</span>
        </button>)}
      </div>

      <div className="sidebar-note">
        <Icon name="spark" size={18}/>
        <div><strong>{t.about}</strong><p>{t.disclaimer}</p></div>
      </div>
    </aside>

    <main className="main-panel" id="top">
      <header className="topbar">
        <div className="search-wrap">
          <Icon name="search" size={19}/>
          <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={t.search} />
          {query && <button className="clear-search" onClick={() => setQuery('')}><Icon name="close" size={16}/></button>}
        </div>
        <div className="visitor-counter" title={lang === 'pt' ? 'Total de visitantes' : 'Total visitors'}>
          <span className="visitor-live-dot" />
          <div className="visitor-counter-content">
            <small>{lang === 'pt' ? 'VISITANTES' : 'VISITORS'}</small>
            <strong>
              {visitorCountLoading
                ? '30.000+'
                : visitorCount.toLocaleString(lang === 'pt' ? 'pt-BR' : 'en-US')}
            </strong>
          </div>
        </div>

        <div className="top-actions">
          <button className="icon-button" onClick={loadStars} title={t.refresh}><Icon name="refresh" size={18}/></button>
          <button
  className="language-button"
  onClick={() => setLang(lang === 'en' ? 'pt' : 'en')}
  title={lang === 'en' ? 'Português' : 'English'}
>
  {lang === 'en' ? (
    <img
      src={brazilFlag}
      alt="Português"
      className="language-flag"
    />
  ) : (
    <span className="language-en">EN</span>
  )}
</button>
          <a className="github-button" href="https://github.com" target="_blank" rel="noreferrer"><Icon name="github" size={19}/><span>GitHub</span></a>
        </div>
      </header>

      <section className="hero-section">
        <div className="hero-copy">
          <span className="eyebrow"><Icon name="spark" size={16}/> Curated GitHub Collection</span>
          <h1>{t.title}</h1>
          <p>{t.subtitle}</p>
          <div className="hero-buttons">
            <a href="#repositories" className="primary-button">{t.repositories}<Icon name="arrow" size={18}/></a>
            <button className="secondary-button" onClick={() => setLang(lang === 'en' ? 'pt' : 'en')}><Icon name="globe" size={18}/>{lang === 'en' ? 'Ver em Português' : 'View in English'}</button>
          </div>
        </div>
        <div className="hero-visual" aria-hidden="true">
          <div className="visual-glow" />
          <div className="floating-card card-a"><Icon name="github" size={29}/><span>Open source</span><strong>{repositories.length} projects</strong></div>
          <div className="floating-card card-b"><Icon name="star" size={25}/><span>GitHub stars</span><strong>{loading ? '...' : formatStars(starTotal)}</strong></div>
          <div className="code-window">
            <div className="window-bar"><i/><i/><i/></div>
            <div className="code-line wide"/><div className="code-line medium"/><div className="code-row"><div className="code-box"/><div className="code-box"/></div><div className="code-row"><div className="code-box tall"/><div className="code-box tall"/></div>
          </div>
        </div>
      </section>

      <section className="stats-grid">
        <div className="stat-card"><span className="stat-icon purple"><Icon name="github"/></span><div><small>{t.projects}</small><strong>{repositories.length}</strong></div></div>
        <div className="stat-card"><span className="stat-icon yellow"><Icon name="star"/></span><div><small>{t.liveStars}</small><strong>{loading ? '...' : formatStars(starTotal)}</strong></div></div>
        <div className="stat-card"><span className="stat-icon green"><Icon name="check"/></span><div><small>{t.freeProjects}</small><strong>{freeCount}</strong></div></div>
        <div className="stat-card"><span className="stat-icon blue"><Icon name="key"/></span><div><small>{t.apiReady}</small><strong>{noApiCount}</strong></div></div>
      </section>

      <section className="video-lab-section" id="video-lab">
        <div className="video-lab-head">
          <div><span className="section-kicker">{t.videoLab}</span><h2>{t.videoTitle}</h2><p>{t.videoSubtitle}</p></div>
          <div className="video-hardware-note"><Icon name="monitor" size={21}/><div><strong>{t.videoHardware}</strong><span>{t.videoTip}</span></div></div>
        </div>

        <div className="video-tool-grid">
          {[
            { repo:'pinokiocomputer/pinokio', name:'Pinokio', label:t.videoEasy, text: lang === 'pt' ? 'Instala e abre projetos locais de IA com uma interface visual. É o caminho mais simples para começar sem viver no terminal.' : 'Installs and launches local AI projects through a visual interface. This is the simplest way to begin without living in the terminal.' },
            { repo:'comfyanonymous/ComfyUI', name:'ComfyUI', label:t.videoStart, text: lang === 'pt' ? 'Monte workflows de imagem e vídeo por nós e reutilize o mesmo fluxo para gerar variações, animações e sequências.' : 'Build node-based image and video workflows and reuse the same graph for variations, animation, and sequences.' },
            { repo:'SkyworkAI/SkyReels-V3', name:'SkyReels V3', label:t.videoAdvanced, text: lang === 'pt' ? 'Geração por referências, áudio e vídeo-para-vídeo. O repositório recomenda Python 3.12+ e CUDA 12.8+.' : 'Reference-guided, audio-guided, and video-to-video generation. The repo recommends Python 3.12+ and CUDA 12.8+.' },
            { repo:'meituan-longcat/LongCat-Video', name:'LongCat Video', label:t.videoHeavy, text: lang === 'pt' ? 'Modelo grande para texto-para-vídeo, imagem-para-vídeo, continuação e avatares. Use quando tiver GPU e espaço suficientes.' : 'A large model for text-to-video, image-to-video, continuation, and avatars. Use it when you have enough GPU memory and storage.' },
            { repo:'Phantom-video/HuMo', name:'HuMo', label:t.videoHeavy, text: lang === 'pt' ? 'Projeto de pesquisa multimodal para vídeos centrados em pessoas usando texto, imagem e áudio como condições.' : 'A multimodal research project for human-centered video using text, image, and audio conditions.' },
            { repo:'FFmpeg/FFmpeg', name:'FFmpeg', label:lang === 'pt' ? 'Finalização' : 'Finishing', text: lang === 'pt' ? 'A ferramenta local para juntar clipes, converter formatos, adicionar áudio, redimensionar, comprimir e preparar o arquivo final.' : 'The local finishing tool for joining clips, converting formats, adding audio, resizing, compressing, and preparing final exports.' },
            { repo:'FujiwaraChoki/MoneyPrinterV2', name:'MoneyPrinter V2', label:lang === 'pt' ? 'Automação' : 'Automation', text: lang === 'pt' ? 'Inclui automação para YouTube Shorts e outros fluxos de conteúdo. Bom para estudar pipelines completos de criação e publicação.' : 'Includes YouTube Shorts automation and other content workflows. Useful for studying end-to-end creation and publishing pipelines.' },
            { repo:'OpenCut-app/OpenCut', name:'OpenCut', label:lang === 'pt' ? 'Editor local' : 'Local editor', text: lang === 'pt' ? 'Editor de vídeo open source para montar um fluxo local de corte e edição sem depender de um editor fechado.' : 'Open-source video editor for building a local cutting and editing workflow without relying on a closed editor.' },
            { repo:'alyssaxuu/motionity', name:'Motionity', label:lang === 'pt' ? 'Motion design' : 'Motion design', text: lang === 'pt' ? 'Ferramenta open source de motion design que pode complementar seus vídeos gerados por IA com animações e elementos visuais.' : 'Open-source motion-design tool that can complement AI-generated videos with animations and visual elements.' },
            { repo:'welovemedia/ffmate', name:'FFmate', label:lang === 'pt' ? 'FFmpeg visual' : 'Visual FFmpeg', text: lang === 'pt' ? 'Interface e utilitários para facilitar tarefas comuns de FFmpeg no fluxo de mídia.' : 'Interface and utilities that make common FFmpeg media tasks easier.' }
          ].map((tool) => <a className="video-tool-card" key={tool.repo} href={`https://github.com/${tool.repo}`} target="_blank" rel="noreferrer">
            <div className="video-tool-icon"><Icon name="github" size={22}/></div><div><span>{tool.label}</span><strong>{tool.name}</strong><p>{tool.text}</p><code>{tool.repo}</code></div><Icon name="external" size={17}/>
          </a>)}
        </div>

        <div className="video-workflow">
          <div className="video-workflow-title"><Icon name="play" size={22}/><div><span>{t.videoSteps}</span><strong>{lang === 'pt' ? 'Do zero ao MP4 local' : 'From zero to a local MP4'}</strong></div></div>
          <div className="video-steps">
            {[
              [t.videoStep1, t.videoStep1Text, '01'],
              [t.videoStep2, t.videoStep2Text, '02'],
              [t.videoStep3, t.videoStep3Text, '03'],
              [t.videoStep4, t.videoStep4Text, '04']
            ].map(([title, text, number]) => <div className="video-step" key={number}><span>{number}</span><div><strong>{title}</strong><p>{text}</p></div></div>)}
          </div>
          <div className="video-quick-links">
            <a href="https://github.com/comfyanonymous/ComfyUI" target="_blank" rel="noreferrer"><Icon name="download" size={17}/>ComfyUI</a>
            <a href="https://github.com/pinokiocomputer/pinokio" target="_blank" rel="noreferrer"><Icon name="download" size={17}/>Pinokio</a>
            <a href="https://github.com/SkyworkAI/SkyReels-V3" target="_blank" rel="noreferrer"><Icon name="download" size={17}/>SkyReels V3</a>
            <a href="https://github.com/FFmpeg/FFmpeg" target="_blank" rel="noreferrer"><Icon name="download" size={17}/>FFmpeg</a>
          </div>
        </div>
      </section>

      <section className="video-lab-section dedicated-lab voice-lab-section" id="voice-lab">
        <div className="video-lab-head">
          <div><span className="section-kicker">{lang === 'pt' ? 'Servidor Local de Voz IA' : 'Local AI Phone Server'}</span><h2>{lang === 'pt' ? 'Hospede um agente que atende chamadas do seu negócio' : 'Host an AI agent that answers your business calls'}</h2><p>{lang === 'pt' ? 'A ideia é manter o cérebro, memória e lógica no seu PC ou servidor. Para receber chamadas de um número telefônico público, você ainda precisa ligar o servidor a SIP/telefonia.' : 'Keep the brain, memory, and business logic on your own PC or server. To receive calls from a public phone number, you still connect the server to SIP/telephony.'}</p></div>
          <div className="video-hardware-note"><Icon name="phone" size={21}/><div><strong>{lang === 'pt' ? 'Stack local recomendado' : 'Recommended local stack'}</strong><span>{lang === 'pt' ? 'Ollama para o LLM + Chatterbox/Dia para voz + Pipecat, LiveKit ou TEN para o agente. SIP/operadora conecta o número real.' : 'Ollama for the LLM + Chatterbox/Dia for speech + Pipecat, LiveKit, or TEN for the agent. SIP/carrier connects the real phone number.'}</span></div></div>
        </div>
        <div className="video-tool-grid">
          {[
            {repo:'livekit/agents',name:'LiveKit Agents',label:lang==='pt'?'Telefonia':'Telephony',text:lang==='pt'?'Framework de agentes em tempo real com integração de telefonia para receber e fazer chamadas. Pode ser auto-hospedado.':'Real-time agent framework with telephony integration for inbound and outbound calls. The stack can be self-hosted.'},
            {repo:'TEN-framework/ten-framework',name:'TEN Framework',label:'SIP + Voice',text:lang==='pt'?'Framework conversacional em tempo real com exemplo de chamada SIP e componentes de VAD/turn detection.':'Real-time conversational framework with SIP-call examples plus VAD and turn-detection components.'},
            {repo:'pipecat-ai/pipecat',name:'Pipecat',label:lang==='pt'?'Orquestração':'Orchestration',text:lang==='pt'?'Pipeline open source para agentes de voz e multimodais em tempo real. Bom para conectar STT, LLM, TTS e telefonia.':'Open-source pipeline for real-time voice and multimodal agents. Useful for connecting STT, LLM, TTS, and telephony.'},
            {repo:'ollama/ollama',name:'Ollama',label:lang==='pt'?'Cérebro local':'Local brain',text:lang==='pt'?'Roda o modelo de linguagem localmente para manter a lógica do agente dentro do seu computador ou servidor.':'Runs the language model locally so the agent brain can stay on your own PC or server.'},
            {repo:'resemble-ai/chatterbox',name:'Chatterbox',label:lang==='pt'?'Voz local':'Local speech',text:lang==='pt'?'TTS open source para gerar a voz do agente localmente.':'Open-source TTS for generating the agent voice locally.'},
            {repo:'nari-labs/dia',name:'Dia',label:lang==='pt'?'Voz expressiva':'Expressive voice',text:lang==='pt'?'Modelo de voz open source que pode complementar a camada de fala do agente.':'Open-source speech model that can complement the agent voice layer.'}
          ].map(tool => <a className="video-tool-card" key={tool.repo} href={`https://github.com/${tool.repo}`} target="_blank" rel="noreferrer"><div className="video-tool-icon"><Icon name="github" size={22}/></div><div><span>{tool.label}</span><strong>{tool.name}</strong><p>{tool.text}</p><code>{tool.repo}</code></div><Icon name="external" size={17}/></a>)}
        </div>
        <div className="lab-callout"><strong>{lang === 'pt' ? 'Fluxo da chamada' : 'Call flow'}</strong><p>{lang === 'pt' ? 'Número/SIP → LiveKit, TEN ou Pipecat → STT → Ollama → suas regras e ferramentas → TTS → resposta na ligação. Você pode manter memória, CRM e lógica no seu próprio servidor.' : 'Phone number/SIP → LiveKit, TEN, or Pipecat → STT → Ollama → your rules and tools → TTS → spoken reply. Memory, CRM integrations, and business logic can stay on your own server.'}</p></div>
      </section>

      <section className="video-lab-section dedicated-lab trading-lab-section" id="trading-lab">
        <div className="video-lab-head">
          <div><span className="section-kicker">{lang === 'pt' ? 'Trading Diário' : 'Daily Trading Lab'}</span><h2>{lang === 'pt' ? 'Pesquisa, sinais, backtesting e paper trading em um só lugar' : 'Research, signals, backtesting, and paper trading in one place'}</h2><p>{lang === 'pt' ? 'Esse espaço é para estudar o mercado todos os dias, testar estratégias e registrar decisões. Deixe paper trading como padrão antes de conectar dinheiro real.' : 'Use this area for daily market research, strategy testing, and decision logs. Keep paper trading as the default before connecting real money.'}</p></div>
          <div className="video-hardware-note"><Icon name="chart" size={21}/><div><strong>{lang === 'pt' ? 'Modo recomendado' : 'Recommended mode'}</strong><span>{lang === 'pt' ? 'Dados → análise → sinal → risco → backtest/paper trade → diário explicando por que ganhou ou perdeu.' : 'Data → analysis → signal → risk → backtest/paper trade → journal explaining why a trade won or lost.'}</span></div></div>
        </div>
        <div className="video-tool-grid">
          {[
            {repo:'OpenBB-finance/OpenBB',name:'OpenBB',label:lang==='pt'?'Dados + pesquisa':'Data + research',text:lang==='pt'?'Base para ações, opções, cripto, forex, macro e renda fixa, com Python e API.':'Foundation for stocks, options, crypto, forex, macro, and fixed income with Python and API access.'},
            {repo:'virattt/ai-hedge-fund',name:'AI Hedge Fund',label:lang==='pt'?'Agentes + Ollama':'Agents + Ollama',text:lang==='pt'?'Equipe de agentes para pesquisa de trading, risco e backtesting. O projeto oferece opção de executar o LLM com Ollama.':'Multi-agent trading research, risk, and backtesting project with an Ollama option for local LLMs.'},
            {repo:'freqtrade/freqtrade',name:'Freqtrade',label:lang==='pt'?'Paper crypto':'Crypto paper',text:lang==='pt'?'Estratégias, backtesting e dry-run para cripto. Comece sempre em dry-run.':'Crypto strategies, backtesting, and dry-run mode. Start in dry-run.'},
            {repo:'mementum/backtrader',name:'Backtrader',label:'Backtesting',text:lang==='pt'?'Framework Python para testar estratégias em dados históricos antes de qualquer execução real.':'Python framework for testing strategies on historical data before any real execution.'},
            {repo:'ranaroussi/yfinance',name:'yfinance',label:lang==='pt'?'Dados rápidos':'Quick data',text:lang==='pt'?'Acesso simples a dados do Yahoo Finance para protótipos e análises diárias.':'Simple Yahoo Finance data access for prototypes and daily analysis.'},
            {repo:'ccxt/ccxt',name:'CCXT',label:lang==='pt'?'Exchanges':'Exchanges',text:lang==='pt'?'API comum para muitas exchanges. Mantenha execução real desligada até você decidir conectar uma corretora/exchange.':'Common API across many exchanges. Keep real execution off until you intentionally connect an exchange.'}
          ].map(tool => <a className="video-tool-card" key={tool.repo} href={`https://github.com/${tool.repo}`} target="_blank" rel="noreferrer"><div className="video-tool-icon"><Icon name="github" size={22}/></div><div><span>{tool.label}</span><strong>{tool.name}</strong><p>{tool.text}</p><code>{tool.repo}</code></div><Icon name="external" size={17}/></a>)}
        </div>
        <div className="lab-callout warning"><strong>{lang === 'pt' ? 'Paper first' : 'Paper first'}</strong><p>{lang === 'pt' ? 'Use esses projetos para pesquisa e simulação primeiro. Nenhum resultado de backtest garante resultado futuro, e conexões com corretora/exchange devem ficar separadas até você escolher habilitar dinheiro real.' : 'Use these projects for research and simulation first. Backtests do not guarantee future results, and broker/exchange execution should stay separate until you choose to enable real money.'}</p></div>
      </section>

      <section className="repositories-section" id="repositories">
        <div className="section-heading">
          <div><span className="section-kicker">{category === 'All' ? t.all : category}</span><h2>{t.repositories}</h2></div>
          <div className="result-tools"><span>{filtered.length} {t.projects.toLowerCase()}</span><button onClick={loadStars} disabled={loading}><Icon name="refresh" size={16}/>{loading ? t.loading : t.refresh}</button></div>
        </div>

        <div className="repo-grid">
          {filtered.map((item) => {
            const data = item[lang];
            const apiText = item.api === 'required' ? t.required : item.api === 'optional' ? t.optional : t.no;
            return <a key={item.repo} id={`repo-${item.repo.replace(/[^a-zA-Z0-9_-]/g, '-')}`} className="repo-card" href={`https://github.com/${item.repo}`} target="_blank" rel="noreferrer" style={{ '--accent': item.accent }}>
              <div className="repo-top">
                <div className="repo-logo"><Icon name="github" size={25}/></div>
                <div className="repo-title"><span>{item.category}</span><h3>{data.name}</h3><code>{item.repo}</code></div>
                <span className="external-icon"><Icon name="external" size={18}/></span>
              </div>

              <div className="star-strip"><Icon name="star" size={19}/><strong>{formatStars(stars[item.repo])}</strong><span>{t.liveStars}</span></div>

              <div className="repo-content">
                <div className="info-block"><span className="info-label">{t.purpose}</span><p>{data.purpose}</p></div>
                <div className="tag-row">
                  <span className={`status-tag ${item.free === 'free' ? 'free' : 'mixed'}`}><Icon name="check" size={14}/>{item.free === 'free' ? t.free : t.mixed}</span>
                  <span className={`status-tag api-${item.api}`}><Icon name="key" size={14}/>{apiText}</span>
                </div>
                <p className="cost-note">{data.why}</p>
                <div className="idea-box"><span><Icon name="spark" size={16}/>{t.idea}</span><p>{data.idea}</p></div>
              </div>

              <div className="repo-footer"><span>{t.open}</span><Icon name="arrow" size={18}/></div>
            </a>;
          })}
        </div>
        {!filtered.length && <div className="empty-state"><Icon name="search" size={30}/><p>{t.noResults}</p></div>}
      </section>

      <footer>{t.disclaimer}</footer>
    </main>
  </div>;
}

createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);